  definition text;
  seed jsonb;
  revised jsonb;
begin
  update public.templates as t
  set data = jsonb_set(t.data, '{cover}', u.value->'cover')
  from jsonb_array_elements(cover_updates) as u(value)
  where t.workspace_id = '00000000-0000-4000-8000-000000000001'::uuid
    and t.data->>'starter_key' = u.value->>'key'
    and exists (
      select 1
      from jsonb_array_elements(u.value->'previous') as previous(cover)
      where previous.cover = t.data->'cover'
    );

  -- Preserve the insert-only trigger and its permissions while updating
  -- the cover fields in the new-workspace payload.
  select pg_catalog.pg_get_functiondef('public.seed_new_workspace_templates()'::regprocedure)
    into definition;
  seed := split_part(definition, '$starter$', 2)::jsonb;
  select jsonb_agg(
    case when u.value is null then item.value
         else jsonb_set(item.value, '{cover}', u.value->'cover') end
    order by item.position
  ) into revised
  from jsonb_array_elements(seed) with ordinality as item(value, position)
  left join jsonb_array_elements(cover_updates) as u(value)
    on item.value->>'starter_key' = u.value->>'key';
  if revised is distinct from seed then
    execute split_part(definition, '$starter$', 1) || '$starter$'
      || revised::text || '$starter$' || split_part(definition, '$starter$', 3);
  end if;
end $migration$;
commit;
